// NewValidationRuntime creates a new runtime state for validation.
func NewValidationRuntime() *ValidationRuntime {
	return &ValidationRuntime{
		Accumulators:          make(map[string]*Accumulator),
		AggregationResults:    make(map[string]interface{}),
		ValidationResults:     []ValidationResult{},
		ReconciliationResults: []ReconciliationResult{},
		ReconciliationScalars: make(map[string]interface{}),
		DocumentContext:       make(map[string]interface{}),
		StartTime:             time.Now(),
		RecordCount:           0,
	}
}

// AddValidationResult adds a validation result to the runtime state.
func (r *ValidationRuntime) AddValidationResult(result ValidationResult) {
	r.ValidationResults = append(r.ValidationResults, result)
}

// GetQualitySummary computes a summary of validation results.
func (r *ValidationRuntime) GetQualitySummary() QualitySummary {
	summary := QualitySummary{
		TotalChecks: len(r.ValidationResults),
	}

	for _, result := range r.ValidationResults {
		if result.Result == "pass" {
			summary.Passed++
		} else {
			switch result.Severity {
			case "info":
				// Info failures don't count as warnings
			case "warning":
				summary.Warnings++
			case "error":
				summary.Errors++
			case "fatal":
				summary.Fatals++
			}
		}
	}

	return summary
}

// ShouldFailExtraction determines if extraction should fail based on policy.
func (r *ValidationRuntime) ShouldFailExtraction(policy FailurePolicy) (bool, error) {
	summary := r.GetQualitySummary()

	// Check for fatal errors
	if policy.FailOnFatal && summary.Fatals > 0 {
		return true, fmt.Errorf("validation failed: %d fatal error(s)", summary.Fatals)
	}

	// Check error threshold (threshold of 0 means any errors fail)
	if policy.ErrorThreshold >= 0 && summary.Errors > policy.ErrorThreshold {
		return true, fmt.Errorf("validation failed: %d errors exceed threshold %d",
			summary.Errors, policy.ErrorThreshold)
	}

	// Warning threshold only logs, doesn't fail
	if policy.WarningThreshold > 0 && summary.Warnings > policy.WarningThreshold {
		// This should be logged but not fail extraction
		return false, nil
	}

	return false, nil
}
